CREATE TABLE inv_skus(id INTEGER PRIMARY KEY,store TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,base_unit TEXT NOT NULL CHECK(base_unit IN ('ml','g','个')),units TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(store,code));
CREATE TABLE inv_costs(id INTEGER PRIMARY KEY,store TEXT NOT NULL,sku_id INTEGER NOT NULL REFERENCES inv_skus(id),effective_at TEXT NOT NULL,cost_micro INTEGER NOT NULL CHECK(cost_micro>=0),source TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(sku_id,effective_at));
CREATE TABLE inv_products(id INTEGER PRIMARY KEY,store TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,document_id INTEGER NOT NULL REFERENCES documents(id),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(store,code));
CREATE TABLE inv_recipe_maps(id INTEGER PRIMARY KEY,store TEXT NOT NULL,revision_id INTEGER NOT NULL UNIQUE REFERENCES revisions(id),lines TEXT NOT NULL,source TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE inv_substitutions(id INTEGER PRIMARY KEY,store TEXT NOT NULL,recipe_map_id INTEGER NOT NULL REFERENCES inv_recipe_maps(id),from_sku_id INTEGER NOT NULL REFERENCES inv_skus(id),to_sku_id INTEGER NOT NULL REFERENCES inv_skus(id),ratio_milli INTEGER NOT NULL CHECK(ratio_milli>0),reason TEXT NOT NULL,safety_note TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT,approved_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE inv_counts(id INTEGER PRIMARY KEY,store TEXT NOT NULL,station TEXT NOT NULL,observed_at TEXT NOT NULL,source TEXT NOT NULL,evidence TEXT NOT NULL,lines TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'submitted' CHECK(state IN ('submitted','approved','rejected')),counted_by INTEGER NOT NULL REFERENCES users(id),approved_by INTEGER REFERENCES users(id),approval_note TEXT,approved_at TEXT,UNIQUE(store,station,observed_at));
CREATE TABLE inv_movements(id INTEGER PRIMARY KEY,store TEXT NOT NULL,station TEXT NOT NULL,sku_id INTEGER NOT NULL REFERENCES inv_skus(id),occurred_at TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('receipt','waste','transfer_in','transfer_out')),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),source TEXT NOT NULL,external_key TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,voided_at TEXT,void_reason TEXT,UNIQUE(store,station,external_key));
CREATE TABLE inv_sales_batches(id INTEGER PRIMARY KEY,store TEXT NOT NULL,station TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,source TEXT NOT NULL,external_key TEXT NOT NULL,is_complete INTEGER NOT NULL,coverage_note TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,voided_at TEXT,void_reason TEXT,UNIQUE(store,station,external_key));
CREATE TABLE inv_sales(id INTEGER PRIMARY KEY,store TEXT NOT NULL,station TEXT NOT NULL,batch_id INTEGER NOT NULL REFERENCES inv_sales_batches(id),external_key TEXT NOT NULL,product_code TEXT NOT NULL,sold_at TEXT NOT NULL,quantity INTEGER NOT NULL,produced_quantity INTEGER NOT NULL CHECK(produced_quantity>=0),net_revenue_fen INTEGER NOT NULL,substitution_ids TEXT NOT NULL,revision_id INTEGER REFERENCES revisions(id),recipe_map_id INTEGER REFERENCES inv_recipe_maps(id),mapping_state TEXT NOT NULL,consumption TEXT NOT NULL,issues TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(store,station,external_key));
CREATE TABLE insight_reports(id INTEGER PRIMARY KEY,store TEXT NOT NULL,station TEXT NOT NULL,start_count_id INTEGER NOT NULL REFERENCES inv_counts(id),end_count_id INTEGER NOT NULL REFERENCES inv_counts(id),inputs TEXT NOT NULL,result TEXT NOT NULL,input_hash TEXT NOT NULL,result_hash TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX inv_sales_window ON inv_sales(store,station,sold_at);
CREATE INDEX inv_movements_window ON inv_movements(store,station,occurred_at);
CREATE TRIGGER immutable_insight_update BEFORE UPDATE ON insight_reports BEGIN SELECT RAISE(ABORT,'Saved reports are immutable'); END;
CREATE TRIGGER immutable_insight_delete BEFORE DELETE ON insight_reports BEGIN SELECT RAISE(ABORT,'Saved reports are immutable'); END;
CREATE TRIGGER immutable_count BEFORE UPDATE ON inv_counts WHEN OLD.state<>'submitted' BEGIN SELECT RAISE(ABORT,'Reviewed count is immutable'); END;
CREATE TRIGGER immutable_recipe_map BEFORE UPDATE ON inv_recipe_maps BEGIN SELECT RAISE(ABORT,'Recipe mapping is immutable'); END;
CREATE TRIGGER immutable_sku BEFORE UPDATE ON inv_skus BEGIN SELECT RAISE(ABORT,'SKU units are immutable'); END;
CREATE TRIGGER immutable_cost BEFORE UPDATE ON inv_costs BEGIN SELECT RAISE(ABORT,'Cost history is immutable'); END;
